using System;
using System.Diagnostics;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Windows.Forms;
namespace Aster {
static class StartupLauncher {
 public static int Duration(int value){return value==1600||value==4200?value:2800;}
 public static string Style(string value){return value=="Warp"||value=="Aurora"?value:"Orbit";}
 public static void Run(){var options=WorkspaceOptions.Read();bool animate=options.StartupEnabled&&options.Motion;if(animate){using(var intro=new StartupScreen(options)){if(intro.ShowDialog()!=DialogResult.OK)return;}}var main=new MainWindow();if(animate)AttachFade(main);Application.Run(main);}
 public static void AttachFade(Form main){var fade=new Timer{Interval=16};var elapsed=new Stopwatch();main.Opacity=0;main.Shown+=(s,e)=>{elapsed.Start();fade.Start();};fade.Tick+=(s,e)=>{main.Opacity=Math.Min(1,elapsed.Elapsed.TotalMilliseconds/240);if(main.Opacity>=1)fade.Stop();};main.FormClosed+=(s,e)=>fade.Dispose();}
}
sealed class StartupScreen:Form {
 readonly Timer frames=new Timer{Interval=25};readonly Stopwatch elapsed=new Stopwatch();readonly ThemePalette palette;readonly string style;readonly int duration;readonly bool motion;readonly Image badge=SuiteArt.Badge(124);readonly PointF[] stars=new PointF[100];bool finished;
 public StartupScreen(WorkspaceOptions options){style=StartupLauncher.Style(options.StartupStyle);duration=StartupLauncher.Duration(options.StartupDuration);motion=options.Motion;palette=ThemePalette.Find(options.ThemeId);if(options.ThemeId=="custom")try{palette=CustomTheme.Create(new ThemeRecipe{Background=options.CustomBase,Accent=options.CustomAccent});}catch{}Text="Welcome to Aster";Icon=SuiteArt.AppIcon();ClientSize=new Size(820,510);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;StartPosition=FormStartPosition.CenterScreen;DoubleBuffered=true;BackColor=palette.Background;KeyPreview=true;AutoScaleMode=AutoScaleMode.None;var random=new Random(74);for(int i=0;i<stars.Length;i++)stars[i]=new PointF((float)random.NextDouble(),(float)random.NextDouble());var skip=new Button{Text="Open Aster  →",AccessibleName="Skip introduction and open Aster",Size=new Size(152,38),Location=new Point(640,445),FlatStyle=FlatStyle.Flat,BackColor=palette.Raised,ForeColor=palette.Text,TabIndex=0};skip.FlatAppearance.BorderColor=palette.Border;skip.Click+=(s,e)=>Complete();Controls.Add(skip);AcceptButton=skip;KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Escape){e.Handled=true;Complete();}};frames.Tick+=(s,e)=>{if(elapsed.ElapsedMilliseconds>=duration){Complete();return;}Invalidate();};Shown+=(s,e)=>{elapsed.Start();frames.Start();};}
 void Complete(){if(finished)return;finished=true;frames.Stop();DialogResult=DialogResult.OK;Close();}
 protected override void Dispose(bool disposing){if(disposing){frames.Dispose();badge.Dispose();}base.Dispose(disposing);}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);Render(e.Graphics,ClientRectangle,elapsed.Elapsed.TotalSeconds);}
 internal void Render(Graphics g,Rectangle bounds,double seconds){g.SmoothingMode=SmoothingMode.AntiAlias;var state=g.Save();g.ScaleTransform(bounds.Width/820f,bounds.Height/510f);using(var background=new LinearGradientBrush(new Rectangle(0,0,820,510),palette.Background,palette.Hero,35f))g.FillRectangle(background,0,0,820,510);double t=motion?seconds:1.5;
 for(int i=0;i<stars.Length;i++){float x=stars[i].X*820,y=stars[i].Y*510;int alpha=100+(int)(55*Math.Sin(t*1.2+i));using(var brush=new SolidBrush(Color.FromArgb(alpha,palette.Accent))){if(style=="Warp"){double travel=(t*.35+stars[i].X)%1;double angle=stars[i].Y*Math.PI*2;float radius=(float)(25+travel*540);x=410+(float)Math.Cos(angle)*radius;y=215+(float)Math.Sin(angle)*radius*.65f;using(var pen=new Pen(Color.FromArgb(alpha,palette.Accent),1.2f))g.DrawLine(pen,x,y,x+(x-410)*.09f,y+(y-215)*.09f);}else g.FillEllipse(brush,x,y,i%5==0?3:1.5f,i%5==0?3:1.5f);}}
 if(style=="Aurora"){for(int band=0;band<5;band++){var pts=new PointF[42];for(int i=0;i<pts.Length;i++){float x=i*20;pts[i]=new PointF(x,210+band*13+(float)Math.Sin(i*.14+t*.8+band*.35)*65);}using(var pen=new Pen(Color.FromArgb(20+band*5,palette.Accent),20))g.DrawCurve(pen,pts);}}
 for(int ring=0;ring<3;ring++){float r=95+ring*28;using(var pen=new Pen(Color.FromArgb(40+ring*12,palette.Accent),1))g.DrawEllipse(pen,410-r,205-r*.58f,r*2,r*1.16f);double angle=t*(.7+ring*.2)+ring*2;float x=410+(float)Math.Cos(angle)*r,y=205+(float)Math.Sin(angle)*r*.58f;using(var glow=new SolidBrush(Color.FromArgb(28,palette.Accent)))g.FillEllipse(glow,x-12,y-12,24,24);using(var dot=new SolidBrush(palette.Accent))g.FillEllipse(dot,x-3,y-3,6,6);}
 float reveal=(float)Math.Min(1,t/0.7);float size=90+34*reveal;g.DrawImage(badge,410-size/2,205-size/2,size,size);using(var font=new Font("Segoe UI",32,FontStyle.Bold))using(var b=new SolidBrush(palette.Text))using(var format=new StringFormat{Alignment=StringAlignment.Center})g.DrawString("A S T E R",font,b,new RectangleF(0,310,820,62),format);using(var font=new Font("Segoe UI",11))using(var b=new SolidBrush(palette.Muted))using(var format=new StringFormat{Alignment=StringAlignment.Center})g.DrawString("A little wonder. A clearer workspace.",font,b,new RectangleF(0,375,820,35),format);using(var font=new Font("Segoe UI",9))using(var b=new SolidBrush(palette.Muted))g.DrawString(style.ToUpperInvariant()+"  /  WELCOME HOME",font,b,28,458);using(var pen=new Pen(palette.Border))g.DrawLine(pen,28,428,792,428);g.Restore(state);}
}
partial class MainWindow {
 void AddStartupPreferences(FlowLayoutPanel flow){flow.Controls.Add(new Label{Text="Make an entrance",AutoSize=true,Font=new Font("Segoe UI",24,FontStyle.Bold)});flow.Controls.Add(new Label{Text="Theme-matched stars, orbital lights, and a smooth workspace reveal.",AutoSize=true,Margin=new Padding(0,8,0,14)});var enabled=new CheckBox{Text="Show the startup introduction",AutoSize=true,Checked=preferences.StartupEnabled};enabled.CheckedChanged+=(s,e)=>{preferences.StartupEnabled=enabled.Checked;SavePreferences();};flow.Controls.Add(enabled);var styles=new ComboBox{Width=280,DropDownStyle=ComboBoxStyle.DropDownList,AccessibleName="Startup animation style"};styles.Items.AddRange(new object[]{"Orbit","Warp","Aurora"});styles.SelectedItem=StartupLauncher.Style(preferences.StartupStyle);styles.SelectedIndexChanged+=(s,e)=>{preferences.StartupStyle=(string)styles.SelectedItem;SavePreferences();};flow.Controls.Add(styles);var length=new ComboBox{Width=280,DropDownStyle=ComboBoxStyle.DropDownList,AccessibleName="Startup animation length"};length.Items.AddRange(new object[]{"Quick · 1.6 seconds","Cinematic · 2.8 seconds","Extended · 4.2 seconds"});int ms=StartupLauncher.Duration(preferences.StartupDuration);length.SelectedIndex=ms==1600?0:ms==4200?2:1;length.SelectedIndexChanged+=(s,e)=>{preferences.StartupDuration=new[]{1600,2800,4200}[length.SelectedIndex];SavePreferences();};flow.Controls.Add(length);var reduced=new CheckBox{Text="Reduce motion throughout Aster (skip startup animation)",AutoSize=true,Checked=!preferences.Motion};reduced.CheckedChanged+=(s,e)=>{preferences.Motion=!reduced.Checked;SavePreferences();ConfigureFun();};flow.Controls.Add(reduced);var replay=Button("Preview introduction ↗");replay.Click+=(s,e)=>{using(var intro=new StartupScreen(preferences))intro.ShowDialog(this);};flow.Controls.Add(replay);flow.Controls.Add(new Label{Text="Enter or Escape skips the intro. Close exits startup. Reduced-motion previews are still.\r\nThis is a visual welcome, not a system scan. Repair tools open directly.",AutoSize=true,Margin=new Padding(0,8,0,28)});}
}
}
